import os
import re
from collections import defaultdict

ROOT = "/bench/repo"

# Data layer: store tree + generated store proto
def is_data_layer(dirpath):
    rel = os.path.relpath(dirpath, ROOT)
    if rel == "store" or rel.startswith("store" + os.sep):
        return True
    if rel == os.path.join("proto", "gen", "store") or rel.startswith(os.path.join("proto", "gen", "store") + os.sep):
        return True
    return False

# Persistent entity types from Driver interface + their related query/mutation types
ENTITIES = {
    "Attachment": ["Attachment", "FindAttachment", "UpdateAttachment", "DeleteAttachment"],
    "Memo": ["Memo", "FindMemo", "UpdateMemo", "DeleteMemo", "FindMemoPayload"],
    "MemoRelation": ["MemoRelation", "FindMemoRelation", "DeleteMemoRelation"],
    "InstanceSetting": ["InstanceSetting", "FindInstanceSetting", "DeleteInstanceSetting"],
    "User": ["User", "FindUser", "UpdateUser", "DeleteUser", "DeleteUserResult"],
    "UserSetting": ["UserSetting", "FindUserSetting", "DeleteUserSetting", "PATQueryResult", "RefreshTokenQueryResult"],
    "IdentityProvider": ["IdentityProvider", "FindIdentityProvider", "UpdateIdentityProvider", "DeleteIdentityProvider", "UpdateIdentityProviderV1"],
    "Inbox": ["Inbox", "FindInbox", "UpdateInbox", "DeleteInbox"],
    "Reaction": ["Reaction", "FindReaction", "DeleteReaction"],
    "MemoShare": ["MemoShare", "FindMemoShare", "DeleteMemoShare"],
    "UserIdentity": ["UserIdentity", "FindUserIdentity", "DeleteUserIdentity"],
}

# Also proto store types (storepb)
PROTO_ENTITIES = {
    "Attachment": ["Attachment", "AttachmentPayload"],
    "Memo": ["MemoPayload", "MemoProperty", "MemoRelationType"],  # memo.proto types
    "InstanceSetting": ["InstanceSetting", "InstanceSettingKey", "InstanceGeneralSetting", "InstanceStorageSetting"],
    "UserSetting": ["UserSetting", "UserSettingKey", "UserGeneralSetting", "UserShortcutsSetting", "UserWebhooksSetting"],
    "IdentityProvider": ["IdentityProvider", "IdentityProviderConfig"],
    "Inbox": ["Inbox", "InboxMessage"],
}

def get_store_import_alias(content):
    """Return alias or 'store' for github.com/usememos/memos/store import."""
    aliases = set()
    for m in re.finditer(r'^\s*([\w]+)\s+"github\.com/usememos/memos/store"', content, re.M):
        aliases.add(m.group(1))
    for m in re.finditer(r'^\s*"github\.com/usememos/memos/store"\s*$', content, re.M):
        aliases.add("store")
    return aliases

def get_storepb_import_alias(content):
    aliases = set()
    for m in re.finditer(r'^\s*([\w]+)\s+"github\.com/usememos/memos/proto/gen/store"', content, re.M):
        aliases.add(m.group(1))
    for m in re.finditer(r'^\s*storepb\s+"github\.com/usememos/memos/proto/gen/store"', content, re.M):
        aliases.add("storepb")
    for m in re.finditer(r'^\s*"github\.com/usememos/memos/proto/gen/store"\s*$', content, re.M):
        aliases.add("storepb")  # common convention
    return aliases

def references_entity(content, aliases, type_names):
    for alias in aliases:
        for tn in type_names:
            # word boundary after type name
            if re.search(r'\b' + re.escape(alias) + r'\.' + re.escape(tn) + r'\b', content):
                return True
    return False

# Track per entity: set of package dirs, and file examples
entity_packages = {e: set() for e in ENTITIES}
entity_files = {e: [] for e in ENTITIES}
entity_proto_packages = {e: set() for e in PROTO_ENTITIES}
entity_proto_files = {e: [] for e in PROTO_ENTITIES}

for dirpath, dirnames, filenames in os.walk(ROOT):
    if ".git" in dirpath.split(os.sep):
        continue
    for fn in filenames:
        if not fn.endswith(".go"):
            continue
        fpath = os.path.join(dirpath, fn)
        if is_data_layer(dirpath):
            continue
        with open(fpath, "r", errors="replace") as f:
            content = f.read()

        pkg_dir = os.path.relpath(dirpath, ROOT)
        store_aliases = get_store_import_alias(content)
        storepb_aliases = get_storepb_import_alias(content)

        for entity, types in ENTITIES.items():
            if store_aliases and references_entity(content, store_aliases, types):
                entity_packages[entity].add(pkg_dir)
                if len(entity_files[entity]) < 5:
                    entity_files[entity].append(fpath)

        for entity, types in PROTO_ENTITIES.items():
            if storepb_aliases and references_entity(content, storepb_aliases, types):
                entity_proto_packages[entity].add(pkg_dir)
                if len(entity_proto_files[entity]) < 3:
                    entity_proto_files[entity].append(fpath)

# Combined counts (union of store struct refs and proto refs)
combined = {}
for entity in ENTITIES:
    combined[entity] = entity_packages[entity] | entity_proto_packages.get(entity, set())

print("=== STORE STRUCT REFERENCES (external packages) ===")
for entity in sorted(ENTITIES, key=lambda e: -len(entity_packages[e])):
    pkgs = sorted(entity_packages[entity])
    print(f"{entity}: {len(pkgs)} packages")
    for p in pkgs:
        print(f"  - {p}")
    print(f"  Example files: {entity_files[entity][:3]}")
    print()

print("\n=== PROTO STORE TYPE REFERENCES (external packages) ===")
for entity in sorted(PROTO_ENTITIES, key=lambda e: -len(entity_proto_packages[e])):
    pkgs = sorted(entity_proto_packages[entity])
    print(f"{entity}: {len(pkgs)} packages")
    for p in pkgs:
        print(f"  - {p}")
    print()

print("\n=== COMBINED RANKING ===")
for entity in sorted(combined, key=lambda e: -len(combined[e])):
    print(f"{entity}: {len(combined[entity])} distinct external packages")
