#!/usr/bin/env perl
use strict;
use warnings;
use File::Find;
use File::Basename;

my $ROOT = "/bench/repo";

sub is_data_layer {
    my ($dir) = @_;
    my $rel = $dir;
    $rel =~ s/^\Q$ROOT\E\/?//;
    return 1 if $rel eq "store" || $rel =~ /^store\//;
    return 1 if $rel eq "proto/gen/store" || $rel =~ /^proto\/gen\/store\//;
    return 0;
}

my %ENTITIES = (
    Attachment => [qw(Attachment FindAttachment UpdateAttachment DeleteAttachment)],
    Memo => [qw(Memo FindMemo UpdateMemo DeleteMemo FindMemoPayload)],
    MemoRelation => [qw(MemoRelation FindMemoRelation DeleteMemoRelation)],
    InstanceSetting => [qw(InstanceSetting FindInstanceSetting DeleteInstanceSetting)],
    User => [qw(User FindUser UpdateUser DeleteUser DeleteUserResult)],
    UserSetting => [qw(UserSetting FindUserSetting DeleteUserSetting PATQueryResult RefreshTokenQueryResult)],
    IdentityProvider => [qw(IdentityProvider FindIdentityProvider UpdateIdentityProvider DeleteIdentityProvider UpdateIdentityProviderV1)],
    Inbox => [qw(Inbox FindInbox UpdateInbox DeleteInbox)],
    Reaction => [qw(Reaction FindReaction DeleteReaction)],
    MemoShare => [qw(MemoShare FindMemoShare DeleteMemoShare)],
    UserIdentity => [qw(UserIdentity FindUserIdentity DeleteUserIdentity)],
);

my %PROTO_ENTITIES = (
    Attachment => [qw(Attachment AttachmentPayload)],
    Memo => [qw(MemoPayload MemoProperty MemoRelationType)],
    InstanceSetting => [qw(InstanceSetting InstanceSettingKey InstanceGeneralSetting InstanceStorageSetting)],
    UserSetting => [qw(UserSetting UserSettingKey UserGeneralSetting UserShortcutsSetting UserWebhooksSetting)],
    IdentityProvider => [qw(IdentityProvider IdentityProviderConfig)],
    Inbox => [qw(Inbox InboxMessage)],
);

my (%entity_packages, %entity_files, %proto_packages, %proto_files);

sub get_store_aliases {
    my ($content) = @_;
    my @aliases;
    while ($content =~ /^\s*(\w+)\s+"github\.com\/usememos\/memos\/store"/gm) {
        push @aliases, $1;
    }
    push @aliases, "store" if $content =~ /^\s*"github\.com\/usememos\/memos\/store"\s*$/m;
    return @aliases;
}

sub get_storepb_aliases {
    my ($content) = @_;
    my @aliases;
    while ($content =~ /^\s*(\w+)\s+"github\.com\/usememos\/memos\/proto\/gen\/store"/gm) {
        push @aliases, $1;
    }
    return @aliases;
}

sub references_entity {
    my ($content, $aliases, $types) = @_;
    for my $alias (@$aliases) {
        for my $tn (@$types) {
            return 1 if $content =~ /\b\Q$alias\E\.\Q$tn\E\b/;
        }
    }
    return 0;
}

find({
    wanted => sub {
        return if /\.git/;
        return unless -f $_ && /\.go$/;
        my $dir = $File::Find::dir;
        return if is_data_layer($dir);

        open my $fh, "<", $_ or return;
        local $/;
        my $content = <$fh>;
        close $fh;

        my $pkg_dir = $dir;
        $pkg_dir =~ s/^\Q$ROOT\E\/?//;

        my @store_aliases = get_store_aliases($content);
        my @storepb_aliases = get_storepb_aliases($content);

        for my $entity (keys %ENTITIES) {
            next unless @store_aliases;
            if (references_entity($content, \@store_aliases, $ENTITIES{$entity})) {
                $entity_packages{$entity}{$pkg_dir} = 1;
                push @{$entity_files{$entity}}, "$dir/$_" if @{$entity_files{$entity} // []} < 5;
            }
        }

        for my $entity (keys %PROTO_ENTITIES) {
            next unless @storepb_aliases;
            if (references_entity($content, \@storepb_aliases, $PROTO_ENTITIES{$entity})) {
                $proto_packages{$entity}{$pkg_dir} = 1;
                push @{$proto_files{$entity}}, "$dir/$_" if @{$proto_files{$entity} // []} < 3;
            }
        }
    },
    no_chdir => 1,
}, $ROOT);

print "=== STORE STRUCT REFERENCES (external packages) ===\n";
for my $entity (sort { scalar(keys %{$entity_packages{$b}}) <=> scalar(keys %{$entity_packages{$a}}) } keys %ENTITIES) {
    my @pkgs = sort keys %{$entity_packages{$entity} // {}};
    print "$entity: ", scalar(@pkgs), " packages\n";
    print "  - $_\n" for @pkgs;
    my @ex = @{$entity_files{$entity} // []};
    print "  Examples: @ex[0..2]\n" if @ex;
    print "\n";
}

print "\n=== PROTO STORE TYPE REFERENCES (external packages) ===\n";
for my $entity (sort { scalar(keys %{$proto_packages{$b}}) <=> scalar(keys %{$proto_packages{$a}}) } keys %PROTO_ENTITIES) {
    my @pkgs = sort keys %{$proto_packages{$entity} // {}};
    print "$entity: ", scalar(@pkgs), " packages\n";
    print "  - $_\n" for @pkgs;
    print "\n";
}

print "\n=== COMBINED RANKING ===\n";
my %combined;
for my $entity (keys %ENTITIES) {
    $combined{$entity}{$_} = 1 for keys %{$entity_packages{$entity} // {}};
    $combined{$entity}{$_} = 1 for keys %{$proto_packages{$entity} // {}};
}
for my $entity (sort { scalar(keys %{$combined{$b}}) <=> scalar(keys %{$combined{$a}}) } keys %combined) {
    print "$entity: ", scalar(keys %{$combined{$entity}}), " distinct external packages\n";
}

