BEGIN {
  split("Attachment Memo MemoRelation InstanceSetting User UserSetting IdentityProvider Inbox Reaction MemoShare UserIdentity", entities, " ")
  for (i in entities) {
    e = entities[i]
    store_types[e] = e "|Find" e "|Update" e "|Delete" e
    if (e == "User") store_types[e] = store_types[e] "|DeleteUserResult"
    if (e == "UserSetting") store_types[e] = store_types[e] "|PATQueryResult|RefreshTokenQueryResult"
    if (e == "IdentityProvider") store_types[e] = store_types[e] "|UpdateIdentityProviderV1"
    if (e == "Memo") store_types[e] = store_types[e] "|FindMemoPayload"
  }
  # proto types per entity
  proto_types["Attachment"] = "Attachment|AttachmentPayload"
  proto_types["Memo"] = "MemoPayload|MemoProperty|MemoRelationType"
  proto_types["InstanceSetting"] = "InstanceSetting|InstanceSettingKey|InstanceGeneralSetting|InstanceStorageSetting|InstanceBasicSetting|InstanceMemoRelatedSetting|InstanceTagsSetting|InstanceNotificationSetting|InstanceAISetting|AIProviderConfig"
  proto_types["UserSetting"] = "UserSetting|UserSettingKey|UserGeneralSetting|UserShortcutsSetting|UserWebhooksSetting|UserAccessTokensSetting|UserNotificationSetting"
  proto_types["IdentityProvider"] = "IdentityProvider|IdentityProviderConfig|IdentityProviderType"
  proto_types["Inbox"] = "Inbox|InboxMessage"
}
function is_data_layer(dir,   rel) {
  rel = dir
  sub(/^\.\//, "", rel)
  if (rel == "store" || rel ~ /^store\//) return 1
  if (rel == "proto/gen/store" || rel ~ /^proto\/gen\/store\//) return 1
  return 0
}
function add_store_alias(content,   n, line) {
  delete store_aliases
  n = split(content, lines, "\n")
  for (i=1; i<=n; i++) {
    line = lines[i]
    if (match(line, /^[[:space:]]*([A-Za-z_][A-Za-z0-9_]*)[[:space:]]+"github\.com\/usememos\/memos\/store"/, m))
      store_aliases[m[1]] = 1
    if (match(line, /^[[:space:]]*"github\.com\/usememos\/memos\/store"[[:space:]]*$/, m))
      store_aliases["store"] = 1
  }
}
function add_storepb_alias(content,   n, line) {
  delete storepb_aliases
  n = split(content, lines, "\n")
  for (i=1; i<=n; i++) {
    line = lines[i]
    if (match(line, /^[[:space:]]*([A-Za-z_][A-Za-z0-9_]*)[[:space:]]+"github\.com\/usememos\/memos\/proto\/gen\/store"/, m))
      storepb_aliases[m[1]] = 1
  }
}
function check_refs(content, aliases, typestr,   tcount, j, alias, types, tn) {
  tcount = split(typestr, types, "|")
  for (alias in aliases) {
    for (j=1; j<=tcount; j++) {
      tn = types[j]
      pat = alias "\\." tn
      if (content ~ pat) return 1
    }
  }
  return 0
}
{
  # handled per file in END via system? no - process files individually
}
'

